     for(i=0;i<modes.length;i++){ if(own._jg) own._jg.t-=17; drawOp(0,300,0,0,'#242832',0,0,modes[i],0,{hero:1,moving:false,sprint:false,ads:false,hurt:0,rl:0,own:own}); if(own._jg) mx=Math.max(mx,Math.abs(own._jg.c)); }
